import { forwardRef, useLayoutEffect, useRef, useState } from 'react';
import type { ButtonHTMLAttributes, AnchorHTMLAttributes, ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './button.css';

/**
 * B10 · Button — one primary per view region. Buttons never move or
 * resize on state change; destructive actions confirm with a typed object.
 */
export type ButtonVariant = 'primary' | 'ghost' | 'danger' | 'link';

interface ButtonOwnProps {
  variant?: ButtonVariant;
  /** POS anatomy: same bones at >=48px height, press feedback <100ms. */
  pos?: boolean;
  /** Swaps the label and locks width to the pre-loading size. */
  isLoading?: boolean;
  /** Label shown while loading, e.g. "Saving…". Required if isLoading is used. */
  loadingLabel?: string;
  /** 16px stroke icon before the label. Icon-only buttons need aria-label. */
  iconLeading?: ReactNode;
  children?: ReactNode;
}

export type ButtonProps = ButtonOwnProps & ButtonHTMLAttributes<HTMLButtonElement>;

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  {
    variant = 'primary',
    pos = false,
    isLoading = false,
    loadingLabel = 'Working…',
    iconLeading,
    className,
    children,
    disabled,
    ...rest
  },
  ref,
) {
  const innerRef = useRef<HTMLButtonElement | null>(null);
  const [lockedWidth, setLockedWidth] = useState<number>();

  /* B10: width locked to pre-loading size while loading. */
  useLayoutEffect(() => {
    if (isLoading && innerRef.current && lockedWidth === undefined) {
      setLockedWidth(innerRef.current.offsetWidth);
    }
    if (!isLoading && lockedWidth !== undefined) {
      setLockedWidth(undefined);
    }
  }, [isLoading, lockedWidth]);

  return (
    <button
      {...rest}
      ref={(node) => {
        innerRef.current = node;
        if (typeof ref === 'function') ref(node);
        else if (ref) ref.current = node;
      }}
      className={cx('sv-btn', `sv-btn--${variant}`, pos && 'sv-btn--pos', className)}
      style={lockedWidth !== undefined ? { ...rest.style, width: lockedWidth } : rest.style}
      disabled={disabled || isLoading}
      aria-busy={isLoading || undefined}
    >
      {isLoading ? (
        <>
          <svg className="sv-btn__spinner" viewBox="0 0 12 12" width="12" height="12" aria-hidden="true">
            <circle cx="6" cy="6" r="5" fill="none" stroke="currentColor" strokeWidth="1.5" strokeDasharray="23" strokeDashoffset="8" strokeLinecap="round" />
          </svg>
          <span>{loadingLabel}</span>
        </>
      ) : (
        <>
          {iconLeading != null && (
            <span className="sv-btn__icon" aria-hidden="true">
              {iconLeading}
            </span>
          )}
          {children}
        </>
      )}
    </button>
  );
});

/** Text-link that looks like a button action (B10 "text link action"). */
export type ButtonLinkProps = AnchorHTMLAttributes<HTMLAnchorElement>;

export function ButtonLink({ className, children, ...rest }: ButtonLinkProps) {
  return (
    <a {...rest} className={cx('sv-btn sv-btn--link', className)}>
      {children}
    </a>
  );
}

/* B10 · Button */

@layer sv-components {
  .sv-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--sv-s2);
    padding: var(--sv-s2) var(--sv-s4);
    border: 1px solid transparent;
    border-radius: var(--sv-r);
    font-size: 12.5px;
    font-weight: 700;
    line-height: 1.4;
    cursor: pointer;
    text-decoration: none;
    transition: background-color var(--sv-t-fast), border-color var(--sv-t-fast), color var(--sv-t-fast);
  }

  .sv-btn--primary {
    background: var(--sv-seed);
    color: var(--sv-paper);
  }

  .sv-btn--primary:hover:not(:disabled),
  .sv-btn--primary:active:not(:disabled) {
    background: var(--sv-seed-deep);
  }

  .sv-btn--ghost {
    background: transparent;
    border-color: var(--sv-line);
    color: var(--sv-ink);
  }

  .sv-band .sv-btn--ghost {
    border-color: var(--sv-band-line);
    color: var(--sv-paper);
  }

  .sv-btn--ghost:hover:not(:disabled) {
    border-color: var(--sv-seed);
  }

  /* Danger = ghost anatomy with bad text. Never a red fill outside a
     dialog's final confirm (use data-confirm on that one button). */
  .sv-btn--danger {
    background: transparent;
    border-color: var(--sv-line);
    color: var(--sv-bad);
  }

  .sv-btn--danger:hover:not(:disabled) {
    border-color: var(--sv-bad);
  }

  .sv-btn--danger[data-confirm] {
    background: var(--sv-bad);
    border-color: transparent;
    color: var(--sv-paper);
  }

  .sv-btn--link {
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--sv-seed-text);
    font-size: 12px;
    font-weight: 600;
  }

  .sv-btn--link:hover {
    text-decoration: underline;
  }

  .sv-btn:disabled {
    background: var(--sv-wall);
    border-color: transparent;
    color: var(--sv-ink-faint);
    cursor: not-allowed;
  }

  /* POS variant: same anatomy at >=48px, press feedback <100ms. */
  .sv-btn--pos {
    min-height: 48px;
    padding: var(--sv-s3) var(--sv-s6);
    font-size: 14.5px;
    transition-duration: 80ms;
  }

  .sv-btn--pos.sv-btn--ghost:active:not(:disabled) {
    background: var(--sv-seed-tint);
  }

  .sv-btn__icon {
    display: inline-flex;
    width: 16px;
    height: 16px;
  }

  /* B10 loading spinner — the ONE registered continuous animation in the
     system (Slop Firewall allowlists `sv-rotate`, see scripts/slop-firewall.mjs). */
  .sv-btn__spinner {
    animation: sv-rotate 800ms linear infinite;
  }

  @keyframes sv-rotate {
    to {
      transform: rotate(360deg);
    }
  }
}
